    fn steam_do(&mut self) {
        // STEAM behavior
        // uml: 1. do [elapsed(steam_cmd_at) >= steam_cmd_max_ms] TransitionTo(IDLE)
        if (self.vars.now_ms.wrapping_sub(self.vars.steam_cmd_at)) >= self.vars.steam_cmd_max_ms {
            // Step 1: Exit states until we reach `ON` state (Least Common Ancestor for transition).
            self.exit_up_to_state_handler(StateId::ON);
            
            // Step 2: Transition action: ``.
            
            // Step 3: Enter/move towards transition target `IDLE`.
            self.idle_enter();
            
            // Step 4: complete transition. Ends event dispatch. No other behaviors are checked.
            return;
        } // end of behavior for STEAM
        
        // STEAM behavior
        // uml: 2. do [after(device_max_steam_ms)] TransitionTo(IDLE)
        if ((self.vars.now_ms.wrapping_sub(self.vars.STEAM_entered_at)) >= self.vars.device_max_steam_ms) {
            // Step 1: Exit states until we reach `ON` state (Least Common Ancestor for transition).
            self.exit_up_to_state_handler(StateId::ON);
            
            // Step 2: Transition action: ``.
            
            // Step 3: Enter/move towards transition target `IDLE`.
            self.idle_enter();
            
            // Step 4: complete transition. Ends event dispatch. No other behaviors are checked.
            return;
        } // end of behavior for STEAM
        
        // STEAM behavior
        // uml: 3. do [elapsed(auto_off_from) >= auto_off_min * 60000] TransitionTo(OFF)
        if (self.vars.now_ms.wrapping_sub(self.vars.auto_off_from)) >= self.vars.auto_off_min.wrapping_mul(60000) {
            // Step 1: Exit states until we reach `MANETTA` state (Least Common Ancestor for transition).
            self.exit_up_to_state_handler(StateId::MANETTA);
            
            // Step 2: Transition action: ``.
            
            // Step 3: Enter/move towards transition target `OFF`.
            self.off_enter();
            
            // Step 4: complete transition. Ends event dispatch. No other behaviors are checked.
            return;
        } // end of behavior for STEAM
        
        // No ancestor handles this event.
    }    
    fn steam_enter_steam(&mut self) {
        let mut consume_event: bool = false;
        
        // STEAM behavior
        // uml: 1. ENTER_STEAM [cmd_max_ms == 0] / { reply = Reply.INVALID; }
        if self.vars.cmd_max_ms == 0 {
            // Consume event `enter_steam`.
            consume_event = true;
            // Step 1: execute action `reply = Reply.INVALID;`
            self.vars.reply = Reply::INVALID;
        } // end of behavior for STEAM
        
        // STEAM behavior
        // uml: 2. ENTER_STEAM [cmd_max_ms != 0] / { reply = Reply.OK; steam_cmd_max_ms = cmd_max_ms; steam_cmd_at = now_ms; }
        if self.vars.cmd_max_ms != 0 {
            // Consume event `enter_steam`.
            consume_event = true;
            // Step 1: execute action `reply = Reply.OK; steam_cmd_max_ms = cmd_max_ms; steam_cmd_at = now_ms;`
            self.vars.reply = Reply::OK; self.vars.steam_cmd_max_ms = self.vars.cmd_max_ms; self.vars.steam_cmd_at = self.vars.now_ms;
        } // end of behavior for STEAM
        
        // Check if event has been consumed before calling ancestor handler.
        if !consume_event {
            self.on_enter_steam();
        }
    }    
